        ctx = self._ctx
        data = await ctx.transport.request("POST", f"/sessions/{quote(session_of(ctx), safe='')}/linear/users/{quote(str(self.id), safe='')}/undelegate", body={"issue": issue.id})
        return (None if data is None else LinearDelivery(ctx, data))

